int fd = 3; // File descriptor for /dev/ttyN
int result;
int ret;

// --- 1. Get LED Status (KDGETLED) ---
// argp required as a pointer to return value
ret = ioctl(fd, KDGETLED, &result);

if (ret == 0) {
    // Success: result holds the LED bitmap
    // e.g., result & LED_CAP == 1
}

// --- 2. Set LED Status (KDSETLED) ---
// argp often used as an integer value for console ioctls
int new_led_mask = 0x03; // Num Lock + Caps Lock
ret = ioctl(fd, KDSETLED, new_led_mask);

// --- 3. Get Keyboard Mode (KDGKBMODE) ---
int mode;
ret = ioctl(fd, KDGKBMODE, &mode);
